{"command":"cat > process.mjs <<'EOF'
import { chromium } from 'playwright';
const b=await chromium.launch({headless:true}); const p=await b.newPage();
await p.goto('http://127.0.0.1:60567/login'); await p.getByLabel('Email').fill('ops@lab.test'); await p.getByLabel('Password').fill('lab-ops-pass'); await p.getByRole('button',{name:'Sign in'}).click(); await p.waitForTimeout(200); await p.goto('http://127.0.0.1:60567/refunds');
const changes=[];
for(let pg=1;pg<=3;pg++){
 await p.waitForTimeout(150);
 const rows=await p.locator('tbody tr').evaluateAll(es=>es.map(e=>({id:e.dataset.id, reason:e.children[2].innerText.trim(), amount:Number(e.children[3].innerText.replace(/[^0-9]/g,'')), blocked:!!e.children[1].querySelector('.badge')&&e.children[1].querySelector('.badge').innerText.trim()==='Blocked', status:e.children[4].innerText.trim()})));
 for(const r of rows){let action=null;if(r.status==='Pending'){if(r.blocked)action='Reject';else if(r.reason==='Damaged item'&&r.amount<=500)action='Approve';}if(action){await p.locator(`tr[data-id="${r.id}"]`).getByRole('button',{name:action}).click(); await p.waitForTimeout(80); changes.push(`${r.id}: ${action}`)}}
 const next=p.locator('a', {hasText:'Next'}); if(pg<3&&await next.count()) await next.click();
}
console.log(changes.join('\n')); await b.close();
EOF
